'use strict';
const Lab={timer:null,cleanup(){if(this.timer)clearInterval(this.timer);this.timer=null;},mount(type,host){this.cleanup();this[type](host);},
greenhouse(host){
 host.innerHTML=`<h2>Nhà kính: đọc → so sánh → điều khiển</h2><div class="lab-grid"><div><label>Nhiệt độ: <output id="temp-out">31</output> °C<input id="temp" type="range" min="0" max="50" value="31"></label><label>Độ ẩm đất: <output id="moisture-out">25</output> %<input id="moisture" type="range" min="0" max="100" value="25"></label><label>Ánh sáng: <output id="light-out">60</output> đơn vị<input id="light" type="range" min="0" max="100" value="60"></label><label><input type="checkbox" id="sensor-fault"> Giả lập mất dữ liệu cảm biến</label><div class="lab-controls"><button class="primary" id="green-step">Bước tiếp</button><button id="green-auto">Chạy chu trình</button><button id="green-reset">Đặt lại</button></div><p class="source-note">Hãy thử 28°C, 35%, 40 đơn vị để kiểm tra biên. Sau một chu trình, tự thay số đo để biểu diễn môi trường đã thay đổi.</p></div><div class="lab-result" id="green-result" aria-live="polite"></div></div>`;
 let stage=0;const el=id=>host.querySelector('#'+id);
 const values=()=>({t:Number(el('temp').value),m:Number(el('moisture').value),l:Number(el('light').value),fault:el('sensor-fault').checked});
 const stop=()=>{this.cleanup();el('green-auto').disabled=false;el('green-step').disabled=false;};
 const draw=()=>{const v=values(),invalid=v.fault||![v.t,v.m,v.l].every(Number.isFinite);['temp','moisture','light'].forEach(id=>el(id+'-out').textContent=el(id).value);
  const labels=['Sẵn sàng: dự đoán trước khi chạy','1 / 4 · Đọc dữ liệu','2 / 4 · So sánh với ngưỡng','3 / 4 · Gửi tín hiệu','4 / 4 · Actuator thực hiện lệnh'];
  const decisions=[v.t>28,v.m<35,v.l<40];
  el('green-result').innerHTML=`<h3>${labels[stage]}</h3><p>${stage===0?'Các lệnh chưa được tính. Điều chỉnh số đo và dự đoán ba đầu ra.':invalid?'Không có số đo tin cậy. Mô hình chặn điều khiển tự động và giữ ba lệnh OFF; cần kiểm tra sensor.':`Đọc được ${v.t}°C · ${v.m}% · ${v.l} đơn vị.`}</p>${stage>=2&&!invalid?`<p>${v.t} > 28: <b>${decisions[0]?'đúng':'sai'}</b><br>${v.m} &lt; 35: <b>${decisions[1]?'đúng':'sai'}</b><br>${v.l} &lt; 40: <b>${decisions[2]?'đúng':'sai'}</b></p>`:''}${['Quạt','Bơm','Đèn'].map((name,i)=>`<div class="status-row"><span>${name}</span><strong>${stage<3?'Chưa gửi lệnh':!invalid&&decisions[i]?'ON':'OFF'}</strong></div>`).join('')}${stage===4?'<p style="margin-top:18px">Motor/đầu ra thực hiện lệnh. Chu trình thực tế sẽ lấy số đo tiếp theo để điều chỉnh.</p>':''}<small>${invalid?'Cách xử lý lỗi này được chọn riêng cho bài mô phỏng; hệ thực tế cần phương án an toàn theo bối cảnh.':'Sensor đo; processor so sánh; actuator tạo tác động.'}</small>`;
 };
 const step=()=>{stage=Math.min(4,stage+1);draw();if(stage===4)stop();};
 ['temp','moisture','light','sensor-fault'].forEach(id=>el(id).addEventListener('input',()=>{stop();stage=0;draw();}));
 el('green-step').onclick=()=>{if(stage===4)stage=0;step();};
 el('green-auto').onclick=()=>{stop();stage=0;el('green-auto').disabled=true;el('green-step').disabled=true;step();this.timer=setInterval(step,900);};
 el('green-reset').onclick=()=>{stop();stage=0;el('temp').value=31;el('moisture').value=25;el('light').value=60;el('sensor-fault').checked=false;draw();};draw();
},
robot(host){
 const contexts={warehouse:{title:'Robot kho: dừng trước vật cản và vận chuyển thùng',sensor:'Distance sensor',processor:'Controller compares distance with a safe limit',actuator:'Wheel motors',why:'Sensor đo khoảng cách; controller kiểm tra mức an toàn; motor bánh xe dừng hoặc di chuyển.'},home:{title:'Robot nhà: phát hiện mép cầu thang',sensor:'Downward-facing cliff sensor',processor:'Controller checks for an edge',actuator:'Wheel motors',why:'Sensor hướng xuống phát hiện thay đổi khoảng cách/phản xạ ở mép; controller quyết định tránh; motor bánh xe dừng/đổi hướng.'},farm:{title:'Robot nông nghiệp: gắp quả đã định vị',sensor:'Camera',processor:'Controller locates the fruit from image data',actuator:'Gripper motor',why:'Camera cung cấp ảnh; controller xác định vị trí; motor của gripper thực hiện gắp. Có camera chưa chứng minh việc định vị dùng ML.'}};
 const choices={sensor:['Camera','Distance sensor','Downward-facing cliff sensor'],processor:['Controller checks for an edge','Controller locates the fruit from image data','Controller compares distance with a safe limit'],actuator:['Gripper motor','Wheel motors','Speaker']};
 host.innerHTML=`<h2>Đọc cấu tạo, chọn bộ phận theo nhiệm vụ</h2><div class="lab-grid"><div><img src="assets/images/05-industrial-robot.png" alt="Robot công nghiệp với tay máy, camera và cơ cấu gắp"><div class="lab-controls"><button data-part="frame">1 · Cơ học</button><button data-part="sensor">2 · Cảm nhận</button><button data-part="controller">3 · Điều khiển</button><button data-part="actuator">4 · Tác động</button></div><p id="robot-part" class="callout" aria-live="polite">Chọn một nhóm bộ phận để giải thích chức năng.</p></div><div><label for="robot-context">Nhiệm vụ</label><select id="robot-context">${Object.entries(contexts).map(([k,v])=>`<option value="${k}">${v.title}</option>`).join('')}</select>${Object.entries(choices).map(([key,opts])=>`<label for="robot-${key}">${key==='sensor'?'Cảm biến':key==='processor'?'Xử lý': 'Actuator'}</label><select id="robot-${key}"><option value="">Chọn thành phần…</option>${opts.map(v=>`<option>${v}</option>`).join('')}</select>`).join('')}<div class="lab-controls"><button class="primary" id="robot-check">Kiểm tra ghép</button><button id="robot-reset">Đặt lại</button></div><div id="robot-result" class="feedback" hidden aria-live="polite"></div></div></div>`;
 const el=id=>host.querySelector('#'+id),parts={frame:'Cấu trúc cơ học: đế, cánh tay, khớp và gripper đỡ hoặc thao tác vật. Không phải thuật toán.',sensor:'Cảm nhận: camera/cảm biến thu dữ liệu về vật hoặc vị trí. Dữ liệu được chuyển tới bộ điều khiển.',controller:'Bộ điều khiển chạy chương trình, dùng dữ liệu để chọn hành động và gửi tín hiệu. Programmable mô tả khả năng quy định hành vi bằng lệnh.',actuator:'Actuator biến tín hiệu thành chuyển động/tác động: motor quay khớp, motor đóng/mở gripper. Đầu công tác tiếp xúc vật.'};
 host.querySelectorAll('[data-part]').forEach(btn=>btn.onclick=()=>{el('robot-part').textContent=parts[btn.dataset.part];host.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));});
 const clear=()=>{Object.keys(choices).forEach(k=>el('robot-'+k).value='');el('robot-result').hidden=true;};el('robot-context').onchange=clear;
 Object.keys(choices).forEach(k=>el('robot-'+k).onchange=()=>el('robot-result').hidden=true);
 el('robot-check').onclick=()=>{const ctx=contexts[el('robot-context').value],keys=Object.keys(choices),vals=keys.map(k=>el('robot-'+k).value),out=el('robot-result');out.hidden=false;if(vals.some(v=>!v)){out.textContent='Chọn đủ ba thành phần trước khi kiểm tra.';return;}const score=keys.filter(k=>el('robot-'+k).value===ctx[k]).length;out.innerHTML=`<b>${score}/3 lựa chọn phù hợp với nhiệm vụ đã mô tả.</b><p>${ctx.why}</p><p>Đối chiếu: ${ctx.sensor} → ${ctx.processor} → ${ctx.actuator}.</p>`;};
 el('robot-reset').onclick=()=>{el('robot-context').value='warehouse';clear();el('robot-part').textContent='Chọn một nhóm bộ phận để giải thích chức năng.';host.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed','false'));};
},
expert(host){
 const facts=[{name:'Tram',surface:'rails',power:'electric'},{name:'Bicycle',surface:'road',power:'pedals'},{name:'Electric car',surface:'road',power:'electric'}];let stage=0;
 host.innerHTML=`<h2>Hệ chuyên gia nhận dạng phương tiện</h2><div class="lab-grid"><div><h3>User interface</h3><label for="expert-surface">Phương tiện hoạt động ở đâu?</label><select id="expert-surface"><option value="">Chưa biết</option value="rails">Rails — đường ray</option><option value="road">Road — đường bộ</option><option value="water">Water — mặt nước</option></select><label for="expert-power">Nguồn lực chuyển động?</label><select id="expert-power"><option value="">Chưa biết</option><option value="electric">Electric — điện</option><option value="pedals">Pedals — bàn đạp</option><option value="diesel">Diesel</option></select><div class="lab-controls"><button class="primary" id="expert-step">Bước tiếp</button><button id="expert-run">Xem cả chu trình</button><button id="expert-reset">Đặt lại</button></div><h3>Knowledge base</h3><div class="table-wrap"><table><thead><tr><th>Object</th><th>Surface</th><th>Power</th></tr></thead><tbody>${facts.map(f=>`<tr><td>${f.name}</td><td>${f.surface}</td><td>${f.power}</td></tr>`).join('')}</tbody></table></div><h3>Rule base</h3><ol>${facts.map(f=>`<li>IF surface = ${f.surface} AND power = ${f.power} THEN ${f.name}</li>`).join('')}</ol></div><div class="lab-result" id="expert-result" aria-live="polite"></div></div>`;
 const el=id=>host.querySelector('#'+id);
 const draw=()=>{const s=el('expert-surface').value,p=el('expert-power').value,match=facts.find(f=>f.surface===s&&f.power===p);let html='<h3>Inference engine · '+stage+'/4 bước</h3>';
  if(stage===0)html+='<p>Chọn dữ kiện rồi theo dõi cách suy luận. Chưa có kết luận.</p>';
  if(stage>=1)html+=`<p><b>1. Nhận dữ kiện qua interface:</b><br>surface = ${s||'chưa biết'}<br>power = ${p||'chưa biết'}</p>`;
  if(stage>=2)html+='<p><b>2. Tra tri thức:</b> kiểm tra các thuộc tính của ba phương tiện trong knowledge base.</p>';
  if(stage>=3)html+=`<p><b>3. Kiểm tra rule base:</b></p><ol>${facts.map(f=>`<li>${f.name}: ${!s||!p?'chưa đủ dữ kiện':f===match?'cả hai điều kiện đều khớp':'không khớp cả hai điều kiện'}</li>`).join('')}</ol>`;
  if(stage>=4)html+=`<h3>4. Kết quả qua interface</h3><p>${!s||!p?'Chưa đủ thông tin. Hãy cung cấp cả surface và power để phân biệt các luật.':match?'Kết luận trong bộ tri thức này: <b>'+match.name+'</b>.':'Không có luật phù hợp. Bộ tri thức này chưa xác định được phương tiện.'}</p>`;
  html+='<small>Chỉ ba đối tượng được mô tả; không tự đoán phương tiện ngoài bộ luật. Sửa dữ kiện để chạy lại.</small>';el('expert-result').innerHTML=html;};
 ['expert-surface','expert-power'].forEach(id=>el(id).onchange=()=>{stage=0;draw();});el('expert-step').onclick=()=>{stage=stage===4?1:stage+1;draw();};el('expert-run').onclick=()=>{stage=4;draw();};el('expert-reset').onclick=()=>{stage=0;el('expert-surface').value='';el('expert-power').value='';draw();};draw();
},
ml(host){
 const original=[{x:2,y:2,label:'A'},{x:3,y:3,label:'A'},{x:2,y:4,label:'A'},{x:6,y:6,label:'A'},{x:8,y:7,label:'B'},{x:8,y:4,label:'B'}];
 const tests=[{x:2,y:3,label:'A'},{x:8,y:6,label:'B'},{x:6,y:5,label:'B'},{x:3,y:2,label:'A'}];let training=original.map(v=>({...v})),model=null,done=false;
 const predict=(input,data)=>{let best=0,dist=Infinity;data.forEach((p,i)=>{const n=(input.x-p.x)**2+(input.y-p.y)**2;if(n<dist){dist=n;best=i;}});return {label:data[best].label,index:best};};
 host.innerHTML=`<h2>Một đầu vào, hai bộ nhãn khác nhau</h2><div class="lab-grid"><div><div id="ml-chart"></div><label>Feature 1: <output id="ml-x-out">6</output><input id="ml-x" type="range" min="0" max="10" step="1" value="6"></label><label>Feature 2: <output id="ml-y-out">5</output><input id="ml-y" type="range" min="0" max="10" step="1" value="5"></label><div class="lab-controls"><button class="primary" id="ml-train">Huấn luyện & dự đoán</button><button id="ml-reset">Đặt lại</button></div><p class="source-note">Chọn mẫu gần nhất theo hai đặc trưng. Nếu bằng khoảng cách, chọn mẫu có số thứ tự nhỏ hơn. Không cần thuộc công thức cho mục tiêu Unit 6.</p></div><div><h3>Dữ liệu huấn luyện — có thể sửa nhãn</h3><div id="ml-data" class="table-wrap data-table"></div><div id="ml-result" class="feedback" aria-live="polite">Chưa huấn luyện. Dự đoán lớp của X trước khi chạy.</div><details><summary>Bốn mẫu kiểm tra giữ riêng</summary><div class="table-wrap"><table><thead><tr><th>X</th><th>Y</th><th>Nhãn đúng</th></tr></thead><tbody>${tests.map(t=>`<tr><td>${t.x}</td><td>${t.y}</td><td>${t.label}</td></tr>`).join('')}</tbody></table></div><p class="source-note">Không dùng các mẫu này làm dữ liệu huấn luyện. Nhãn chỉ dùng để đối chiếu kết quả.</p></details></div></div>`;
 const el=id=>host.querySelector('#'+id),input=()=>({x:Number(el('ml-x').value),y:Number(el('ml-y').value)});
 const chart=()=>{const v=input(),px=x=>48+x*35,py=y=>380-y*33;el('ml-x-out').textContent=v.x;el('ml-y-out').textContent=v.y;el('ml-chart').innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 450 430" role="img" aria-label="Sáu mẫu huấn luyện và điểm X cần dự đoán"><path d="M48 40 V380 H405" stroke="#698295" fill="none" stroke-width="2"/>${[0,2,4,6,8,10].map(n=>`<text x="${px(n)}" y="402" text-anchor="middle" font-size="13" fill="#486477">${n}</text><text x="31" y="${py(n)+5}" text-anchor="middle" font-size="13" fill="#486477">${n}</text>`).join('')}<text x="200" y="423" font-size="14" fill="#183247">Feature 1</text><text x="10" y="23" font-size="14" fill="#183247">Feature 2</text>${training.map((p,i)=>`${p.label==='A'?`<circle cx="${px(p.x)}" cy="${py(p.y)}" r="9" fill="#305ac8"/>`:`<rect x="${px(p.x)-9}" y="${py(p.y)-9}" width="18" height="18" fill="#bd790e"/>`}<text x="${px(p.x)+13}" y="${py(p.y)-9}" font-size="14" fill="#36566c">${i+1}</text>`).join('')}<path d="M${px(v.x)-9} ${py(v.y)-9} l18 18 M${px(v.x)-9} ${py(v.y)+9} l18 -18" stroke="#142c40" stroke-width="4"/><text x="${px(v.x)+13}" y="${py(v.y)+17}" font-size="16" fill="#142c40">X</text></svg><p class="source-note">● Xanh = A · ■ Vàng = B · × = đầu vào mới (${v.x}, ${v.y})</p>`;};
 const result=()=>{if(!model){el('ml-result').innerHTML='Dữ liệu chưa được huấn luyện hoặc đã đổi nhãn. Bấm “Huấn luyện & dự đoán” để dùng bộ nhãn hiện tại.';return;}const p=predict(input(),model),results=tests.map(t=>({...predict(t,model),truth:t.label})),score=results.filter(t=>t.label===t.truth).length;el('ml-result').innerHTML=`<h3>Dự đoán X: ${p.label}</h3><p>Mẫu huấn luyện gần nhất: #${p.index+1} (${model[p.index].x}, ${model[p.index].y}), nhãn ${model[p.index].label}.</p><p><b>Kiểm tra giữ riêng: ${score}/4 đúng (${score*25}%).</b></p><p>${results.map((r,i)=>`Mẫu ${i+1}: dự đoán ${r.label}, nhãn đúng ${r.truth} — ${r.label===r.truth?'đúng':'sai'}`).join('<br>')}</p><p class="answer-status">Kết quả chỉ áp dụng cho bốn mẫu này. Thử đổi nhãn mẫu #4 từ A sang B, giữ X=(6,5), rồi huấn luyện lại.</p>`;};
 const data=()=>{el('ml-data').innerHTML=`<table><thead><tr><th>Mẫu</th><th>(F1, F2)</th><th>Nhãn</th></tr></thead><tbody>${training.map((p,i)=>`<tr><td>#${i+1}</td><td>(${p.x}, ${p.y})</td><td><button data-label="${i}" aria-label="Đổi nhãn mẫu ${i+1}, hiện là ${p.label}">${p.label} ↔</button></td></tr>`).join('')}</tbody></table>`;el('ml-data').querySelectorAll('[data-label]').forEach(btn=>btn.onclick=()=>{const p=training[Number(btn.dataset.label)];p.label=p.label==='A'?'B':'A';model=null;data();chart();result();});};
 ['ml-x','ml-y'].forEach(id=>el(id).oninput=()=>{chart();if(done)result();});el('ml-train').onclick=()=>{model=training.map(p=>({...p}));done=true;chart();result();};el('ml-reset').onclick=()=>{training=original.map(p=>({...p}));model=null;done=false;el('ml-x').value=6;el('ml-y').value=5;data();chart();el('ml-result').textContent='Chưa huấn luyện. Dự đoán lớp của X trước khi chạy.';};data();chart();
}
};
